INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('3.2.2-meta-siniestros', 0, 'indicador_impacto', '3.2.2', 'Reducción de siniestros con ciclistas/VMP (indicador de impacto)', 'ciudad', NULL, NULL, NULL, '-50 % en 2030 (línea base «—», sin año de referencia)', 'sin_info', NULL, '2026-11-04', 1, NULL, 'PDF p.65 (pág. 62), l.3080', '«Reducción de siniestros con ciclistas/VMP» −50 %, comparación anual, fuente Policía Local', 'No hay datos de 2026 publicados en el portal, así que no se puede evaluar. Única cifra pública de 2026: balance de 100 días del Plan Vector (Policía Local, ene-may 2026 frente a ene-may 2025): 50 siniestros con VMP menos (El Periòdic, 10/06/2026, https://www.elperiodic.com/valencia/plan-vector-policia-local-para-reducir-accidentes-mortales-comienza-frutos-solo-muerto-frente-siete-2025_1079063). Seguimiento del observatorio: base 2025 (1.659 siniestros con bici o VMP; meta 830 en 2030).');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('3.2.2-carril-bici-km', 1, 'medida', '3.2.2', 'Seguir creando carriles bici segregados (y bajar a la calzada los que van por la acera)', 'ciudad', NULL, NULL, NULL, '225 km → 250 km de carril bici', 'en_marcha', '2026-07-27', '2026-11-07', 8, 8, 'PDF p.65 (pág. 62), l.3068', '«Km de carriles bici construidos» 225 → 250; PDF p.42, l.1845-1870', 'Hay obra en curso (Giorgeta-Pérez Galdós, ver fila propia) y varias licitaciones en 2026: Campos Crespo (03/07), Albereda (16/10), tres lotes (22/10), redacción del proyecto de Av. del Port (27/10). Buena parte son traslados a la calzada, que no suman km. No hay ningún recuento oficial de km posterior al de 27/11/2025 (225,7 km). Memoria de actuaciones 2023-2026: +19 km de carril bici y +12,35 km de ciclocalles desde 09/2023. Terminados en 2025-2026: Tres Forques (3.887 m, 12/2025), Camí Nou de Picanya-Arxiduc Carles (2.266 m, 09-12/2025), Dr. Tomàs Sala (1 de 4 actuaciones, 11/2025), Joaquim Navarro (300 m, 01/2026) y Sant Vicent Màrtir (1.600 m, 04/2026). En obra: Gaspar Aguilar (1.200 m). No da el total de km: la línea base (225 km) no se puede actualizar.');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('3.2.2-ciclocalles', 2, 'medida', '3.2.2', 'Ampliar las ciclocalles', 'ciudad', NULL, NULL, NULL, '18 km → 75 km de ciclocalles', 'en_marcha', '2026-09-22', '2026-11-04', 3, 3, 'PDF p.65 (pág. 62), l.3070', '«Km de ciclocalles» 18 → 75', 'Duda de línea base: el Plan da 18 km, pero el Ajuntament ya hablaba de 46,89 km el 27/11/2025 y la prensa de más de 54 km en 09/2026. Las nuevas salen de los presupuestos participativos. No se ha encontrado la nota municipal original. Nuevas en 09/2026: C/ Serpis (2.365 m) y vial de la plaza Jardí de Wangari Maathai (1.097 m), de los presupuestos participativos. La Memoria de actuaciones da +12,35 km de ciclocalles desde 09/2023.');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('3.2.2-alfombras-rojas', 3, 'medida', '3.2.2', 'Alfombras rojas señalizadas en carriles bici', 'ciudad', NULL, NULL, NULL, '786 → 1.000', 'sin_info', NULL, '2026-11-04', 1, NULL, 'PDF p.65 (pág. 62), l.3072', '; responsable en la tabla: Urbanismo', 'No se ha encontrado ningún recuento ni anuncio posterior al Plan. El carril de Giorgeta-Pérez Galdós incluye cruces pintados de rojo, pero no se publica el número.');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('3.2.2-pasos-contenedores', 4, 'medida', '3.2.2 e)', 'Pasos de peatones sobre el carril bici para acceder a los contenedores', 'ciudad', NULL, NULL, NULL, '3 → 100', 'sin_info', NULL, '2026-11-04', 1, NULL, 'PDF p.65 (pág. 62), l.3075', '; línea e) de 3.2.2 (PDF p.42, l.1867)', 'La Memoria de actuaciones 2023-2026 dice que entre 2024 y 06/2026 se hicieron 1.277 pasos de peatones nuevos, incluidos pasos sobre el carril bici, y que muchos se están señalizando para acceder a los contenedores. No da cuántos ni dónde. Preguntar el recuento al Servicio.');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('3.2.2-plan-director-bici', 5, 'medida', '3.2.2', 'Ejecutar las actuaciones del Plan Director de la Bicicleta (2023)', 'ciudad', NULL, NULL, NULL, '100 % de las actuaciones', 'sin_info', NULL, '2026-11-04', 1, NULL, 'PDF p.65 (pág. 62), l.3078', '«Actuaciones del Plan Director de la Bicicleta ejecutadas» 100 %', 'No hay ningún seguimiento publicado del Plan Director de la Bicicleta. Proyectos sueltos lo citan (p. ej. la redacción del proyecto de Av. del Port, 27/10/2026). La «Memoria de actuaciones de movilidad 2023-2026» (07/2026, https://www.valencia.es/documents/d/guest/20260727-memoria-actuaciones-movilidad-2023-2026-julio-2026) no da el grado de avance (leída el 04/11/2026); solo cita el Plan Director de la Bicicleta para el carril de l''Albereda.');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('3.2.2-zonas-lista', 6, 'medida', '3.2.2', 'Identificar las zonas de elevada siniestralidad con ciclistas y/o VMP y proponer medidas específicas', 'ciudad', NULL, NULL, NULL, NULL, 'sin_info', NULL, '2026-11-04', 1, NULL, 'PDF p.42, l.1845', '«Proponer medidas específicas de seguridad vial en zonas de elevada siniestralidad con ciclistas y/o usuarios de VMP implicados extensibles a toda la ciudad»', 'El Plan no define qué es una zona de elevada siniestralidad ni publica la lista (solo los 3 primeros cruces y calles de 2.3.4). La nota municipal del 03/02/2026 dice que el Departamento de Análisis Viario de la Policía Local identificará estas zonas (https://www.valencia.es/cas/actualidad/-/content/plan-director-de-seguridad-vial-val%C3%A8ncia).');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('3.2.2c-ambar-intermitente', 7, 'medida', '3.2.2 c)', 'Eliminar la fase ámbar intermitente en determinadas intersecciones', 'ciudad', NULL, NULL, NULL, NULL, 'en_marcha', '2026-08-27', '2026-11-04', 4, 4, 'PDF p.42, l.1860', '«c) Estudiar la eliminación de la fase ámbar intermitente en determinadas intersecciones»', 'Primera fase hecha (Albereda-Pont de l''Exposició en los dos sentidos y Pl. de Saragossa hacia el Pont d''Aragó y hacia l''Albereda). La nota anuncia que se seguirá «semanalmente» en otros cruces; no se ha encontrado la lista posterior. Antes de la aprobación del Plan, pero la nota la enmarca en él. Fuente anterior: https://www.valencia.es/cas/actualidad/-/content/cambios-semaf%C3%B3ricos-en-el-plan-del-real-val%C3%A8ncia (07/05/2026). Lista de la Memoria de actuaciones 2023-2026 (apdo. 5.5): Tarongers-Lluís Peixó (03/2026); Alcalde Reig-Regne de València (04/2026); en 05/2026, Pl. de Saragossa (giros a Pont d''Aragó y a l''Albereda), Pont de l''Exposició-Albereda, Mestre Rodrigo-Vall de la Ballestera, Pont de Montolivet-Albereda, Av. Catalunya-Blasco Ibáñez, Ausiàs March-Av. de la Plata, Blasco Ibáñez-Cardenal Benlloch, Blasco Ibáñez-Serradora, Tarongers-Ramon Llull, Cardenal Benlloch-Av. del Port, Jacinto Benavente-Peris i Valero, 9 d''Octubre-Pintor Stolz, Albereda-Menorca, Professor López Piñero-Pont de l''Assut de l''Or y Germans Machado-Joan XXIII. Mapa municipal: https://www.google.com/maps/d/u/1/viewer?mid=12T1_6G3wKqRYUdxhyKLF3CLjGNs3cFU. El 27/08/2026 el Ajuntament habla de 20 cruces.');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('3.2.2b-semaforizacion-carriles-bici', 8, 'medida', '3.2.2 b)', 'Extender la semaforización en los carriles bici más conflictivos', 'ciudad', NULL, NULL, NULL, NULL, 'anunciada', '2026-09-17', '2026-11-04', 5, 5, 'PDF p.42, l.1855', '«b) Reforzar la señalización en intersecciones no reguladas y revisar las fases semafóricas en intersecciones reguladas»', 'Fuente: lista oficial de anuncios del Debate (copia en docs/contexto/anuncis_debat_estat_ciutat_2026.pdf); la URL es la convocatoria del Debate. No dice qué carriles ni cuándo.');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('3.2.2-resto-lineas', 9, 'medida', '3.2.2 a) d) f) g) h) i)', 'Resto de líneas de 3.2.2: visibilidad en intersecciones y cruces peatonales, bici en zonas peatonales, paradas de bus, ciclistas en calzada, continuidad de la red', 'ciudad', NULL, NULL, NULL, NULL, 'sin_info', NULL, '2026-11-04', 1, NULL, 'PDF p.42, l.1850-1875', ' (líneas a, d, f, g, h, i)', 'Solo hay medidas sueltas en cruces auditados (ver filas de lugar). No hay ningún programa ni lista publicada para estas líneas. Antecedentes en la Memoria de actuaciones 2023-2026: iluminación de pasos de peatones desde 2025 (línea g), carril bici de la acera convertido en ciclocalle en Agustí Alaman i Rodrigo (09/2025, líneas d e i) y bajada a la calzada en la Av. de la Plata (licitada en 05/2026). Son anteriores al Plan y no forman un programa.');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('1.3.1-paneles-contadores', 10, 'medida', '1.3.1', 'Paneles contadores de intensidad en la infraestructura ciclista', 'ciudad', NULL, NULL, NULL, '3 → 9 paneles', 'sin_info', NULL, '2026-11-04', 1, NULL, 'PDF p.63 (pág. 60), l.2972', '; responsable en la tabla: Urbanismo', 'No se ha encontrado ningún panel nuevo. Sí se publica la IMD mensual de las espiras (p. ej. «imd bici 2026-09», web de Movilidad), que no son paneles.');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('1.3.1-aparcabicis', 11, 'medida', '1.3.1', 'Plazas de aparcabicis', 'ciudad', NULL, NULL, NULL, '22.638 → 25.000', 'sin_info', NULL, '2026-11-04', 1, NULL, 'PDF p.63 (pág. 60)', '«Plazas de aparca-bici» 22.638 → 25.000', 'No hay instalaciones publicadas tras la aprobación. Antes: 22.958 plazas según el Ajuntament (27/11/2025), más que la línea base del Plan.');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('1.3.1-desplazamientos-bici-vmp', 12, 'medida', '1.3.1', 'Incremento de desplazamientos en bici/VMP (aforos de los carriles bici)', 'ciudad', NULL, NULL, NULL, '+3,4 % → +5 %', 'sin_info', NULL, '2026-11-04', 1, NULL, 'PDF p.63 (pág. 60), l.2978', NULL, 'Indicador, no actuación. Movilidad publica la IMD mensual de los carriles bici, pero no el indicador. elDiario.es (25/09/2026) informa de que el uso del carril bici baja por primera vez desde 2020 (contador de Xàtiva: 9.350 al día en el primer semestre de 2025 frente a 6.500 en 2026). Calculable por el observatorio con panel fijo.');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('1.2.1-campanas-convivencia', 13, 'medida', '1.2.1 / 1.2.2', 'Campañas de concienciación y divulgación (convivencia entre modos, bici y VMP)', 'ciudad', NULL, NULL, NULL, '8 campañas; 40 acciones divulgativas', 'sin_info', NULL, '2026-11-04', 1, NULL, 'PDF p.62 (pág. 59), l.2917 y l.2923', NULL, 'Nada publicado desde el 23/07/2026. Antecedentes: «¡Tú eres el chasis!» (2024) y la campaña de concienciación y control de VMP de la Policía Local de febrero de 2025 (El Periòdic, 17/02/2025).');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('1.2.4-web-seguridad-vial', 14, 'medida', '1.2.4', 'Apartado web de seguridad vial con datos de siniestralidad y memoria de actuaciones', 'ciudad', NULL, NULL, NULL, 'Portal operativo; 20 actualizaciones; 40.000 visitas', 'sin_info', NULL, '2026-11-04', 6, NULL, 'PDF p.62 (pág. 59), l.2944', '; texto de la acción en l.1338-1342: «apartado con datos de siniestralidad, memoria de actuaciones, etc.»', 'La web existe, pero sin el apartado de datos que prevé el Plan: aloja el Plan y su síntesis, pero no tiene datos de siniestralidad, mapa ni memoria de actuaciones. La Memoria de actuaciones de movilidad 2023-2026 está en valencia.es, pero la sección de seguridad vial no la enlaza (04/11/2026) y no trae datos de siniestralidad.');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('2.1-controles-vmp', 15, 'medida', '2.1', 'Controles policiales segmentados, con atención a VMP (ocupación, casco, velocidad, registro) y vigilancia de los carriles bici (GIVIC)', 'ciudad', NULL, NULL, NULL, 'Sin meta numérica (remite al Plan Vector)', 'en_marcha', '2026-02-23', '2026-11-07', 20, 20, 'PDF p.33 (pág. 30), l.1457', '«condiciones de ocupación del vehículo (especialmente en VMP), uso de casco»', 'GIVIC (12 agentes en patinete por el carril bici) desde el 23/02/2026 (https://www.valencia.es/cas/actualidad/-/content/grupo-inspecci%C3%B3n-v%C3%ADas-ciclistas). Campaña de registro de VMP en junio de 2026 (https://www.valencia.es/cas/actualidad/-/content/campa%C3%B1a-control-inscripci%C3%B3n-patinetes-val%C3%A8ncia). Balance del primer semestre: casi 500 VMP retirados (El Español, 10/06/2026). Todo es anterior a la aprobación del Plan; no se ha encontrado balance posterior al 23/07/2026.');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('3.5-calles-30', 16, 'medida', '3.5 / 3.5.1', 'Ampliar las calles 30', 'ciudad', NULL, NULL, NULL, '64 % → 95 % de las calles', 'sin_info', NULL, '2026-11-04', 1, NULL, 'PDF p.67 (pág. 64), l.3146', '«Calles 30» 64 % → 95 %', 'No se ha encontrado ninguna ampliación anunciada desde la aprobación. Tampoco hay capa pública de calles 30 para medirlo.');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('3.5-calles-20', 17, 'medida', '3.5', 'Calles 20, residenciales y zonas de coexistencia', 'ciudad', NULL, NULL, NULL, '3 % → 10 % de las calles', 'sin_info', '2026-07-27', '2026-11-07', 8, NULL, 'PDF p.67 (pág. 64), l.3142', '«Calles 20 y residenciales» 3 % → 10 %', 'Nueva zona de coexistencia de 20 km/h en Campanar y cambio de señal en Ciutat Vella (esto último es adaptación al Reglamento, no ampliación). Anterior a la aprobación del Plan. En 09/2026, 20 km/h en C/ Professor Ernest Lluch (con las ciclocalles). No se publica el porcentaje. Según la Memoria de actuaciones 2023-2026, hoy el 2,39 % de las calles (casi 26 km) está limitado a 20 km/h; además, el 0,72 % son residenciales, el 1,06 % zonas de coexistencia y el 0,07 % de estancia y juego. No está claro si se suman ni cómo casan con el 3 % de línea base del Plan: preguntarlo. Otras medidas de 2026 anteriores al Plan: El Palmar a 20 km/h (03/2026) y entorno del IES Cabanyal a 20 y 30 km/h (04/2026).');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('3.5-evaluacion-zonas30', 18, 'medida', '3.5.1', 'Evaluar la efectividad de las zonas 30 y de preferencia residencial', 'ciudad', NULL, NULL, NULL, '-50 % de siniestros en zonas 30, de coexistencia y residenciales', 'sin_info', NULL, '2026-11-04', 1, NULL, 'PDF p.67 (pág. 64), l.3160', '; texto en l.2162', 'No se ha encontrado ninguna evaluación publicada.');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('3.6-manual-obras', 19, 'medida', '3.6', 'Manual municipal de señalización de obras que tenga en cuenta la micromovilidad', 'ciudad', NULL, NULL, NULL, 'Manual aprobado; -40 % de incidentes en obras', 'sin_info', NULL, '2026-11-04', 1, NULL, 'PDF p.67 (pág. 64), l.3165', '; texto en l.2258-2267', 'No se ha encontrado nada publicado.');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('3.7-auditorias', 20, 'medida', '3.7', 'Auditorías de seguridad vial en tramos críticos en servicio (y en proyectos)', 'ciudad', NULL, NULL, NULL, '4 → 30 auditorías en servicio; 10 proyectos auditados', 'sin_info', NULL, '2026-11-04', 1, NULL, 'PDF p.67 (pág. 64), l.3173-3175', '«Nº Auditorías en tramos críticos en servicio» 4 → 30', 'Solo constan las 4 de 2024 (presentadas en 09/2024). Sus resultados se están aplicando (ver filas de lugar), pero no se ha encontrado ningún contrato ni anuncio de auditorías nuevas. La Memoria de actuaciones 2023-2026 (apdo. 5.1) solo describe las 4 de 2024 y añade que «se trabaja en coordinación con Policía Local». No hay contrato de auditorías nuevas en el buscador de contratos (04/11/2026; llega a 06/2026).');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('6.1.1-mapa-siniestros', 21, 'medida', '6.1.1 c)', 'Aplicaciones para ver en un mapa las consultas a la base de datos de siniestros', 'ciudad', NULL, NULL, NULL, '5 módulos informáticos', 'sin_info', NULL, '2026-11-04', 1, NULL, 'PDF p.53, l.2439', '«c) Desarrollar aplicaciones que permitan visualizar en un mapa los resultados de las consultas a la base de datos»', 'No hay visor público. La web de seguridad vial (consultada el 04/11/2026) solo enlaza mapas de tráfico e intensidades. El Plan no dice si será público.');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('6.1.1-informes-indicadores', 22, 'medida', '6.1.1 b)', 'Indicadores siniestros/IMD e informes de indicadores de siniestralidad', 'ciudad', NULL, NULL, NULL, '6 informes publicados al año', 'sin_info', NULL, '2026-11-04', 1, NULL, 'PDF p.70 (pág. 67), l.3290', '«Informes de análisis de indicadores de siniestralidad vial» 6/año', 'No se ha encontrado ningún informe publicado. La nota del 03/02/2026 anunciaba revisiones trimestrales y evaluaciones anuales.');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('6.2-convenios', 23, 'medida', '6.2', 'Convenios de colaboración con universidades y entidades investigadoras', 'ciudad', NULL, NULL, NULL, '10 convenios; 15 estudios; 6 pilotos', 'sin_info', NULL, '2026-11-04', 1, NULL, 'PDF p.70 (pág. 67), l.3295', NULL, 'No se ha encontrado ningún convenio de seguridad vial del Ajuntament desde la aprobación.');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('7.1.1-cuadro-mando', 24, 'medida', '7.1.1', 'Cuadro de mando de seguimiento del Plan', 'ciudad', NULL, NULL, NULL, 'No existente → sistema operativo', 'sin_info', NULL, '2026-11-04', 1, NULL, 'PDF p.71 (pág. 68), l.3320', '«Cuadro de mando de seguimiento del PDSVV implantado», línea base «No existente»', 'No se ha encontrado. El Plan no dice si será público.');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('7.1.2-memoria-anual', 25, 'medida', '7.1.2', 'Memoria anual de siniestralidad para la Comisión de Seguridad Vial de la Mesa de la Movilidad', 'ciudad', NULL, NULL, NULL, '1 informe anual publicado (línea base 1)', 'sin_info', NULL, '2026-11-04', 1, NULL, 'PDF p.71 (pág. 68), l.3323', '«Nº informes anuales publicados» 1 → 1/año', 'No se ha encontrado ninguna memoria de siniestralidad publicada. La «Memoria de actuaciones de movilidad 2023-2026» (07/2026) es un resumen de obras y medidas del Servicio de Movilidad, sin cifras de siniestralidad (leída el 04/11/2026): no cuenta como memoria de siniestralidad.');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('7.3.1-informes-comision', 26, 'medida', '7.3.1', 'Informes de seguimiento ante la Comisión de Seguridad Vial', 'ciudad', NULL, NULL, NULL, '2 al año', 'sin_info', NULL, '2026-11-04', 1, NULL, 'PDF p.71 (pág. 68), l.3341', NULL, 'No se ha encontrado ninguna convocatoria ni acta de la Comisión desde la aprobación.');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('7.3.4-empresas-bici-vmp', 27, 'medida', '7.3.4', 'Implicar a empresas de venta y alquiler de bicis y VMP en campañas', 'ciudad', NULL, NULL, NULL, '5 → 30 empresas', 'sin_info', NULL, '2026-11-04', 1, NULL, 'PDF p.71 (pág. 68), l.3345', NULL, 'No se ha encontrado nada publicado.');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('3.2.2-pl-zaragoza', 28, 'medida', '3.7 / 3.2.2 c)', 'Reordenación de la glorieta y fin del ámbar intermitente (auditoría de 2024)', 'lugar', 'Pl. de Saragossa (Albereda, Aragó, Port)', -0.360756, 39.468258, NULL, 'hecha', '2026-05-07', '2026-11-04', 9, 9, 'PDF p.22, l.863', 'cruce n.º 1 en siniestros con VMP (32) y con bici (22), 2019-2025; PDF p.23, l.909-948: auditoría 2024 y reordenación 2025', 'Feb. 2025: carriles pintados y rojo fijo en el giro Aragó→Albereda (Valencia News, 22/02/2025). Mayo de 2026: fin del ámbar en dos ramales más. Es el cruce más siniestrado del Plan para bici y VMP: buen candidato para medir el antes y el después cuando haya datos de 2026.');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('3.7-blasco-benlloch-clariano', 29, 'medida', '3.7 / 3.2.2', 'Remodelación de la glorieta partida en glorieta circular (auditoría de 2024)', 'lugar', 'Av. de Blasco Ibáñez - Av. Cardenal Benlloch - C/ Clariano', -0.35262, 39.47503, NULL, 'anunciada', '2026-09-30', '2026-11-04', 10, 10, 'PDF p.23 (pág. 20), l.909 y l.948', 'auditoría 2024 y reordenación de intersección crítica en 2025', 'Proyecto aprobado con presupuesto base de licitación de 973.082,87 € y 6 meses de obra; no se ha encontrado licitación ni adjudicación. La auditoría cita «conflictos con los itinerarios ciclistas». Medidas previas hechas en mayo de 2025: marcas viales, LED en el paso de Clariano, retirada de un mupi y de una papelera del carril bici (El Periòdic, 08/05/2025). Anuncio n.º 32 del Debate del Estado de la Ciudad (17/09/2026): «eliminación del punto de gran siniestralidad». Fin del ámbar intermitente en Blasco Ibáñez-Cardenal Benlloch en 05/2026 (Memoria de actuaciones 2023-2026, apdo. 5.5). La obra de la glorieta no aparece en el buscador de contratos del Ajuntament (04/11/2026; llega a 06/2026).');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('3.7-granvia-guimera', 30, 'medida', '3.7', 'Medidas provisionales de la auditoría de 2024 (fin del ámbar y rojo más largo)', 'lugar', 'Gran Via de Ferran el Catòlic - C/ Àngel Guimerà', -0.385269, 39.470359, NULL, 'hecha', '2025-02-22', '2026-11-04', 1, 22, 'PDF p.23 (pág. 20), l.948', '«intersecciones críticas» reordenadas en 2025', 'Medida sobre todo peatonal (boca de metro en la mediana). Prensa: Valencia News, 22/02/2025 (https://valencianews.es/valencia/movilidad-senaliza-los-carriles-de-plaza-zaragoza-y-mejora-la-seguridad-viaria-de-la-rotonda/). No se ha encontrado ninguna obra definitiva posterior.');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('3.7-benlloch-puerto', 31, 'medida', '3.7', 'Actuación tras la auditoría de 2024', 'lugar', 'Av. Cardenal Benlloch - Av. del Port', -0.356482, 39.46709, NULL, 'hecha', '2025-02-22', '2026-11-07', 22, 22, 'PDF p.23 (pág. 20), l.911', 'una de las 4 auditorías de 2024', 'Auditada en 2024. La Memoria de actuaciones 2023-2026 dice que en los cuatro puntos auditados se impulsaron medidas (señalización de carriles, fases semafóricas, visibilidad del carril bici, pasos peatonales) y lo incluye en la eliminación del ámbar de 05/2026. No detalla qué se hizo en este cruce.');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('3.2.2-ausias-abril', 32, 'medida', '3.2.2', 'Medidas en cruce de elevada siniestralidad con VMP', 'lugar', 'Av. d''Ausiàs March - Av. Fernando Abril Martorell', -0.369242, 39.446485, NULL, 'sin_info', NULL, '2026-11-04', 1, NULL, 'PDF p.22 (pág. 19), l.863', 'cruce n.º 2 en siniestros con VMP (25), 2019-2025', 'El Plan lo señala en el diagnóstico, pero no le asigna actuación. No se ha encontrado nada publicado. Ojo: la Memoria de actuaciones cita el fin del ámbar en Ausiàs March-Av. de la Plata (05/2026), que es otro cruce.');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('3.2.2-naranjos-peixo', 33, 'medida', '3.2.2', 'Medidas en cruce de elevada siniestralidad con VMP y bici', 'lugar', 'Av. dels Tarongers - C/ Lluís Peixó', -0.333318, 39.476075, NULL, 'en_marcha', '2026-07-27', '2026-11-04', 8, 8, 'PDF p.22 (pág. 19), l.863 y l.868', 'n.º 3 en VMP (22) y n.º 2 en bici (15), 2019-2025', 'El Plan lo señala en el diagnóstico, pero no le asigna actuación. Única medida publicada: fin del ámbar intermitente en 03/2026 (Memoria de actuaciones 2023-2026, apdo. 5.5). No hay obra ni proyecto publicados.');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('3.2.2-abril-malilla', 34, 'medida', '3.2.2', 'Medidas en cruce de elevada siniestralidad con bici', 'lugar', 'Av. Fernando Abril Martorell - Ctra. de Malilla', -0.380195, 39.446119, NULL, 'sin_info', NULL, '2026-11-04', 1, NULL, 'PDF p.22 (pág. 19), l.870', 'cruce n.º 3 en siniestros con bici (14), 2019-2025', 'El Plan lo señala en el diagnóstico, pero no le asigna actuación. No se ha encontrado nada publicado.');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('3.2.2-xativa-jesus', 35, 'medida', '3.2.2', 'Estudiar la configuración ciclista: giro de vehículos con ámbar sobre el paso de peatones y el carril bici', 'lugar', 'C/ Xàtiva - C/ Jesús', -0.3796, 39.46865, NULL, 'sin_info', NULL, '2026-11-04', 1, NULL, 'PDF p.40 (pág. 37), l.1775', '«Cruces con giro de vehículos a motor y regulación semafórica con fase ámbar […] (marginal derecha, calle Xátiva con calle Jesús, etc.)»', 'No se ha encontrado nada publicado. Podría entrar en la eliminación progresiva del ámbar (fila 3.2.2c). Coordenada: la de la Pl. de Sant Agustí (lugar n.º 11), donde la C/ Xàtiva da paso a la C/ Jesús; los dos ejes no se tocan (137 m entre sí) y el punto medio anterior caía sobre Guillem de Castro (corregido el 06/11/2026).');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('3.2.2-jardin-turia', 36, 'medida', '3.2.2', 'Medidas en la zona de concentración de VMP y calle n.º 1 en siniestros con bici', 'lugar', 'Jardí del Túria', NULL, NULL, NULL, 'sin_info', NULL, '2026-11-04', 1, NULL, 'PDF p.22 (pág. 19), l.867', 'calle n.º 1 en siniestros con bici (185); PDF p.41, l.1803: uso de VMP concentrado «a lo largo del Jardín del Turia»', 'No se ha encontrado ninguna medida de seguridad para bici o VMP en el cauce. Sí está en obra un camino ciclopeatonal en el tramo XVI-Pont de les Drassanes (2,04 M€, Junta de Gobierno del 10/10/2025, previsto para finales de 2026), que no responde al Plan. Sin coordenadas: es una zona lineal de unos 9 km y el portal no geolocaliza estos siniestros. El camino ciclopeatonal tramo XVI-pont de les Drassanes se formalizó el 12/06/2026 con Orthem por 1.874.423,25 € (exp. 04101/2026/2-O): https://contrataciondelestado.es/wps/poc?uri=deeplink:detalle_licitacion&idEvl=O57tLw%2FBLx6TylGzYmBF9Q%3D%3D. Es obra de red, no una medida de seguridad en el cauce.');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('3.2.2-albereda-carril', 37, 'medida', '3.2.2', 'Traslado a la calzada del carril bici del Passeig de l''Albereda (Pont del Regne-Pont de Montolivet, unos 450 m)', 'lugar', 'Passeig de l''Albereda (Pont del Regne-Pont de Montolivet)', -0.357518, 39.461474, NULL, 'anunciada', '2026-10-19', '2026-11-04', 11, 11, 'PDF p.22, l.862', 'Paseo de la Alameda, calle n.º 3 en siniestros con VMP (166), 2019-2025', 'Licitación aprobada, sin adjudicar: por eso «anunciada». La nota no cita el Plan de Seguridad Vial ni la siniestralidad. El tramo queda al sur de la Pl. de Saragossa. Coordenada de referencia: cruce con el Pont del Regne. Según la Memoria de actuaciones, el proyecto se aprobó en 06/2026 (476.778,34 €, 450 m, 3 meses). Nota municipal de la licitación (16/10/2026): https://www.valencia.es/cas/actualidad/-/content/licitaci%C3%B3n-modificaci%C3%B3n-carril-bici-albereda. Sin adjudicación publicada a 04/11/2026.');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('3.2.2-puerto-carril', 38, 'medida', '3.2.2', 'Redacción del proyecto para bajar a la calzada el carril bici de la Av. del Port (tres tramos)', 'lugar', 'Av. del Port', -0.347296, 39.464262, NULL, 'anunciada', '2026-10-22', '2026-11-04', 12, 12, 'PDF p.22, l.862 y l.867', 'Av. del Puerto, calle n.º 2 en VMP (167) y n.º 3 en bici (110), 2019-2025', 'Solo se licita el proyecto (ofertas hasta el 06/11/2026), no la obra. Lo enmarca en el Plan Director de la Bicicleta, no en el de Seguridad Vial. Coordenada aproximada: mediana de los siniestros geocodificados de la avenida. Nota municipal: https://www.valencia.es/cas/actualidad/-/content/licitaci%C3%B3n-redacci%C3%B3n-proyecto-carril-bici-avenida-del-puerto-val%C3%A8ncia (27/10/2026). Anuncio en la Plataforma de Contratación publicado y sin adjudicar a 04/11/2026.');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('3.2.2-campos-crespo', 39, 'medida', '3.2.2', 'Carril bici de Campos Crespo, Pius XI y Conca (1,1 km)', 'lugar', 'C/ Campos Crespo - C/ Pius XI - C/ Conca', -0.399878, 39.453483, NULL, 'anunciada', '2026-10-01', '2026-11-07', 30, 30, 'PDF p.22, l.875', 'Tres Cruces - Campos Crespo, cruce n.º 3 en atropellos (7)', 'Licitación aprobada; no se ha encontrado adjudicación. Incluye mejoras de seguridad peatonal. Coordenada aproximada: mediana de los siniestros geocodificados de la calle. La licitación de la obra (exp. 04101/2026/117-O, 649.298,21 €) quedó desierta: ninguna oferta (resultado publicado el 12/08/2026): https://contrataciondelestado.es/wps/poc?uri=deeplink:detalle_licitacion&idEvl=3O8TtcPDS30wYTJJ03sHog%3D%3D. La de la dirección de obra (exp. 04101/2026/122-SEROB) acabó en renuncia (25/08/2026). No consta nueva licitación en la Plataforma a 31/10/2026.');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('3.2.2-giorgeta-perez-galdos', 40, 'medida', '3.2.2', 'Carril bici bidireccional segregado en Giorgeta y Pérez Galdós (reurbanización)', 'lugar', 'Av. de Giorgeta - Av. de Pérez Galdós', -0.388323, 39.464516, NULL, 'en_marcha', '2026-09-09', '2026-11-04', 14, 14, 'PDF p.22, l.875', 'Giorgeta - Jesús, cruce n.º 2 en atropellos (8)', 'Obra de Urbanismo en fase final (algunos tramos terminados); no es una actuación del Plan, pero suma km de carril bici. No se ha encontrado la nota municipal. Coordenada aproximada: mediana de los siniestros geocodificados de las dos avenidas. Contrato formalizado el 12/06/2025 con la UTE Pavasal-Grupo Bertolín por 23.956.817,83 € (exp. 04101/2024/334-O): https://contrataciondelestado.es/wps/poc?uri=deeplink:detalle_licitacion&idEvl=V3KrMzimy3k%2B1TMyIiZmzw%3D%3D');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('3.2.2-itinerarios-3-lotes', 41, 'medida', '3.2.2', 'Mejora de itinerarios ciclistas en tres lotes: C/ Carters, C/ Burgos y Av. de la Plata', 'lugar', 'C/ Carters; C/ Burgos; Av. de la Plata', NULL, NULL, NULL, 'anunciada', '2026-10-22', '2026-11-04', 15, 15, 'PDF p.65 (pág. 62), l.3068', ' (km de carril bici)', 'Sin coordenadas: son tres calles distintas. La Av. de la Plata ya se había licitado el 26/05/2026 por 152.014,64 € (bajar el carril a la calzada en dos glorietas); no se explica la diferencia de importe. Nota municipal: https://www.valencia.es/cas/actualidad/-/content/obras-mejora-itinerarios-ciclistas-val%C3%A8ncia (22/10/2026). Anuncio en la Plataforma de Contratación publicado y sin adjudicar a 04/11/2026. La licitación de la Av. de la Plata de 05/2026 (exp. 04101/2026/87-O, propuesta n.º 5008) quedó desierta, sin ofertas (adjudicación publicada el 29/06/2026: https://contrataciondelestado.es/wps/poc?uri=deeplink:detalle_licitacion&idEvl=YkI%2FJpgVW9rjHF5qKI4aaw%3D%3D); la propuesta 5008 vuelve en estos tres lotes.');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('3.2.2-gaspar-aguilar', 42, 'medida', '3.2.2', 'Carril bici bidireccional segregado en la Av. de Gaspar Aguilar (1.200 m, pl. de Jesús-Dr. Tomàs Sala)', 'lugar', 'Av. de Gaspar Aguilar', -0.3922, 39.453677, '225 km → 250 km de carril bici', 'en_marcha', '2026-07-27', '2026-11-04', 8, 8, 'PDF p.43 (pág. 40), l.1844', '3.2.2 «Continuar con la mejora de la seguridad vial en los itinerarios ciclistas existentes»', 'Obra de Movilidad iniciada en 09/2025, que acaba en 2026 según la Memoria; no es una actuación del Plan, pero suma km. Contrato formalizado el 14/08/2025 (exp. 04101/2025/30-O, lote de 1.391.151,82 €, Alcudia Servicios y Obras): https://contrataciondelestado.es/wps/poc?uri=deeplink:detalle_licitacion&idEvl=A%2BhQh9rSB6xPpzdqOdhuWg%3D%3D. Coordenadas: mediana de los siniestros geocodificados de la avenida (coords_plan_seguimiento.py; aproximada).');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('1.1.3-viveros-vmp', 43, 'medida', '1.1.3', 'Centro de Educación Vial de Viveros: formación de escolares con distintos vehículos, incluidos los VMP', 'ciudad', NULL, NULL, NULL, '150 visitas, 5.000 alumnos y 85 % de centros al año', 'sin_info', NULL, '2026-11-04', 1, NULL, 'PDF p.30 (pág. 27), l.1285-1289', '«practiquen utilizando para su movilidad distintos tipos de vehículos, incluyendo VMPs»; indicadores en PDF p.61 (pág. 58), l.2890-2898', 'Sin información pública buscada todavía (añadida en la v2). Preguntar a la Policía Local por las visitas y el uso de VMP en el centro.');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('3.2.3c-carril-bici-escolar', 44, 'medida', '3.2.3 c)', 'Completar la red de carriles bici en el entorno escolar, conectada con la red ciclista de la ciudad', 'ciudad', NULL, NULL, NULL, 'Sin meta propia (3.2.3: -60 % de siniestros en el entorno escolar)', 'sin_info', NULL, '2026-11-04', 1, NULL, 'PDF p.43 (pág. 40), l.1927', '«Completar la red de carriles bici en el entorno escolar conectada con la malla ciclista de la ciudad»', 'Sin información pública buscada todavía (añadida en la v2).');
INSERT INTO plan_actuacion (id, orden, clase, accion_plan, actuacion, ambito, lugar, lon, lat, meta, estado, fecha_fuente, fecha_comprobacion, fuente_id, fuente_estado_id, ref_plan, texto_plan, nota) VALUES ('3.2.2-nicolas-factor', 45, 'medida', '3.2.2', 'Mejora del itinerario ciclista y peatonal en la C/ del Beat Nicolau Factor, entre la C/ de María Jordán y la C/ de l''Assagador de les Monges (presupuestos participativos 2022-2023)', 'lugar', 'C/ Beat Nicolau Factor (María Jordán - Assagador de les Monges)', -0.391671, 39.461548, 'Sin meta propia', 'anunciada', '2026-10-20', '2026-11-04', 16, 16, 'PDF p.43 (pág. 40), l.1844', '3.2.2 «Continuar con la mejora de la seguridad vial en los itinerarios ciclistas existentes»', 'Licitación publicada el 20/10/2026 por 236.232,97 €, sin adjudicar. No se ha encontrado nota municipal. La licitación la llama «C/ Nicolás Factor»; en el callejero municipal es la C/ Beat Nicolau Factor (codvia 9450; «Beato Nicolás Factor» en castellano), que se cruza con María Jordán y con Assagador de les Monges. Coordenadas: punto medio del eje del callejero entre esos dos cruces (coords_plan_seguimiento.py).');
